```python
"""
Comprehensive WhatsApp Web Element Mapper
==========================================
This script systematically explores WhatsApp Web and documents EVERY element
with exact selectors, workflows, and sequential steps.

Usage:
    python comprehensive_whatsapp_mapper.py
"""

from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.action_chains import ActionChains
from selenium.common.exceptions import TimeoutException, NoSuchElementException
import json
import time
from datetime import datetime
import os

class WhatsAppElementMapper:
    def __init__(self, driver=None):
        """Initialize the mapper with a Selenium WebDriver"""
        if driver is None:
            chrome_options = webdriver.ChromeOptions()
            chrome_options.add_argument("--user-data-dir=C:\\selenium\\User_Data")
            chrome_options.add_argument("--profile-directory=Default")
            self.driver = webdriver.Chrome(options=chrome_options)
            self.driver.get("https://web.whatsapp.com/")
            print("⏳ Please scan QR code if needed... Waiting 15 seconds...")
            time.sleep(15)
        else:
            self.driver = driver

        self.wait = WebDriverWait(self.driver, 10)
        self.elements_mapping = {
            "version": "4.0_COMPLETE",
            "mapped_date": datetime.now().isoformat(),
            "sections": {}
        }
        self.workflows = {}

    def get_element_details(self, element):
        """Extract all details from an element"""
        try:
            return {
                "tag_name": element.tag_name,
                "id": element.get_attribute("id") or "",
                "class": element.get_attribute("class") or "",
                "aria-label": element.get_attribute("aria-label") or "",
                "role": element.get_attribute("role") or "",
                "data-icon": element.get_attribute("data-icon") or "",
                "data-tab": element.get_attribute("data-tab") or "",
                "title": element.get_attribute("title") or "",
                "type": element.get_attribute("type") or "",
                "placeholder": element.get_attribute("placeholder") or "",
                "name": element.get_attribute("name") or "",
                "contenteditable": element.get_attribute("contenteditable") or "",
                "text": element.text[:100] if element.text else "",  # Limit to 100 chars
                "xpath": self.get_xpath(element),
                "css_selector": self.get_css_selector(element)
            }
        except Exception as e:
            print(f"⚠️ Error getting element details: {e}")
            return {}

    def get_xpath(self, element):
        """Generate XPath for element"""
        try:
            # Use JavaScript to generate XPath
            script = """
            function getXPath(element) {
                if (element.id !== '')
                    return 'id("' + element.id + '")';
                if (element === document.body)
                    return element.tagName;

                var ix = 0;
                var siblings = element.parentNode.childNodes;
                for (var i = 0; i < siblings.length; i++) {
                    var sibling = siblings[i];
                    if (sibling === element)
                        return getXPath(element.parentNode) + '/' + element.tagName + '[' + (ix + 1) + ']';
                    if (sibling.nodeType === 1 && sibling.tagName === element.tagName)
                        ix++;
                }
            }
            return getXPath(arguments[0]);
            """
            return self.driver.execute_script(script, element)
        except:
            return ""

    def get_css_selector(self, element):
        """Get CSS selector for element"""
        try:
            # Try simple selectors first
            if element.get_attribute("id"):
                return f"#{element.get_attribute('id')}"

            aria_label = element.get_attribute("aria-label")
            if aria_label:
                return f'[aria-label="{aria_label}"]'

            data_icon = element.get_attribute("data-icon")
            if data_icon:
                return f'[data-icon="{data_icon}"]'

            return ""
        except:
            return ""

    def map_section(self, section_name, description):
        """Start mapping a new section"""
        print(f"\n{'='*60}")
        print(f"📍 MAPPING: {section_name}")
        print(f"   {description}")
        print(f"{'='*60}\n")

        self.elements_mapping["sections"][section_name] = {
            "description": description,
            "elements": {},
            "workflows": {}
        }

    def add_element(self, section_name, element_name, element, notes=""):
        """Add an element to the mapping"""
        details = self.get_element_details(element)
        self.elements_mapping["sections"][section_name]["elements"][element_name] = {
            **details,
            "notes": notes
        }
        print(f"  ✅ Captured: {element_name}")
        if details.get("aria-label"):
            print(f"      aria-label: {details['aria-label']}")
        if details.get("data-icon"):
            print(f"      data-icon: {details['data-icon']}")

    def add_workflow(self, section_name, workflow_name, steps):
        """Add a workflow with sequential steps"""
        self.elements_mapping["sections"][section_name]["workflows"][workflow_name] = {
            "steps": steps,
            "step_count": len(steps)
        }
        print(f"  📝 Workflow Added: {workflow_name} ({len(steps)} steps)")

    def map_main_interface(self):
        """Map the main WhatsApp Web interface"""
        self.map_section("main_interface", "Main WhatsApp Web interface layout and navigation")

        try:
            # Left Sidebar Tabs
            print("  🔍 Finding left sidebar navigation tabs...")
            tabs = self.driver.find_elements(By.CSS_SELECTOR, "div[role='region'] button[aria-label]")
            for tab in tabs:
                label = tab.get_attribute("aria-label")
                if label:
                    self.add_element("main_interface", f"tab_{label.lower().replace(' ', '_')}", tab)

            # Header buttons
            print("  🔍 Finding header buttons...")
            header_buttons = self.driver.find_elements(By.CSS_SELECTOR, "header button, header div[role='button']")
            for btn in header_buttons:
                aria_label = btn.get_attribute("aria-label")
                if aria_label:
                    self.add_element("main_interface", f"header_{aria_label.lower().replace(' ', '_')}", btn)

            # Search input
            print("  🔍 Finding search input...")
            search_inputs = self.driver.find_elements(By.CSS_SELECTOR, "div[contenteditable='true'][data-tab]")
            for search in search_inputs:
                data_tab = search.get_attribute("data-tab")
                if data_tab:
                    self.add_element("main_interface", f"search_input_tab{data_tab}", search)

            # Chat list container
            print("  🔍 Finding chat list container...")
            chat_list = self.driver.find_elements(By.CSS_SELECTOR, "#pane-side")
            if chat_list:
                self.add_element("main_interface", "chat_list_container", chat_list[0], "Scrollable chat list")

            # Menu button and dropdown
            print("  🔍 Finding menu button...")
            menu_buttons = self.driver.find_elements(By.CSS_SELECTOR, "button[aria-label='Menu']")
            if menu_buttons:
                self.add_element("main_interface", "main_menu_button", menu_buttons[0])

                # Click menu to reveal items
                menu_buttons[0].click()
                time.sleep(1)

                print("  🔍 Finding menu items...")
                menu_items = self.driver.find_elements(By.CSS_SELECTOR, "li[role='button'], div[role='button']")
                for idx, item in enumerate(menu_items):
                    if item.text:
                        self.add_element("main_interface", f"menu_item_{item.text.lower().replace(' ', '_')}", item)

                # Close menu
                self.driver.find_element(By.TAG_NAME, "body").click()
                time.sleep(0.5)

        except Exception as e:
            print(f"  ⚠️ Error mapping main interface: {e}")

    def map_chat_interface(self):
        """Map chat conversation interface"""
        self.map_section("chat_interface", "Individual chat conversation view")

        try:
            # Find and click first chat
            print("  🔍 Opening first available chat...")
            chats = self.driver.find_elements(By.CSS_SELECTOR, "#pane-side div[role='listitem']")
            if not chats:
                print("  ⚠️ No chats found, using alternative selector...")
                chats = self.driver.find_elements(By.CSS_SELECTOR, "div[data-testid='cell-frame-container']")

            if chats:
                chats[0].click()
                time.sleep(2)

                # Chat header
                print("  🔍 Mapping chat header...")
                chat_header_buttons = self.driver.find_elements(By.CSS_SELECTOR, "header button, header span[data-icon]")
                for btn in chat_header_buttons:
                    aria_label = btn.get_attribute("aria-label") or btn.get_attribute("data-icon")
                    if aria_label:
                        self.add_element("chat_interface", f"header_{aria_label.replace(' ', '_')}", btn)

                # Message input area
                print("  🔍 Mapping message compose area...")
                message_input = self.driver.find_elements(By.CSS_SELECTOR, "div[contenteditable='true'][data-tab='10']")
                if message_input:
                    self.add_element("chat_interface", "message_input_box", message_input[0], "Main message compose box")

                # Input area buttons
                footer_buttons = self.driver.find_elements(By.CSS_SELECTOR, "footer button, footer span[data-icon]")
                for btn in footer_buttons:
                    data_icon = btn.get_attribute("data-icon")
                    aria_label = btn.get_attribute("aria-label")
                    name = data_icon or (aria_label.replace(' ', '_') if aria_label else "")
                    if name:
                        self.add_element("chat_interface", f"input_button_{name}", btn)

                # Attachment menu  (click plus button)
                print("  🔍 Mapping attachment menu...")
                plus_buttons = self.driver.find_elements(By.CSS_SELECTOR, "span[data-icon='plus'], span[data-icon='attach-menu-plus']")
                if plus_buttons:
                    plus_buttons[0].click()
                    time.sleep(1)

                    attach_items = self.driver.find_elements(By.CSS_SELECTOR, "span[data-icon]")
                    seen_icons = set()
                    for item in attach_items:
                        icon = item.get_attribute("data-icon")
                        if icon and icon not in seen_icons and icon not in ['plus', 'attach-menu-plus']:
                            seen_icons.add(icon)
                            try:
                                parent_btn = item.find_element(By.XPATH, "./ancestor::button[1]")
                                self.add_element("chat_interface", f"attachment_{icon}", parent_btn)
                            except:
                                pass

                    # Close attachment menu
                    self.driver.find_element(By.TAG_NAME, "body").click()
                    time.sleep(0.5)

                # Emoji picker
                print("  🔍 Mapping emoji picker...")
                emoji_buttons = self.driver.find_elements(By.CSS_SELECTOR, "span[data-icon='smiley']")
                if emoji_buttons:
                    for btn in emoji_buttons:
                        try:
                            parent = btn.find_element(By.XPATH, "./ancestor::button[1]")
                            parent.click()
                            time.sleep(1)

                            emoji_panel = self.driver.find_elements(By.CSS_SELECTOR, "div[role='tablist']")
                            if emoji_panel:
                                tabs = emoji_panel[0].find_elements(By.CSS_SELECTOR, "button[role='tab']")
                                for tab in tabs:
                                    aria_label = tab.get_attribute("aria-label")
                                    if aria_label:
                                        self.add_element("chat_interface", f"emoji_tab_{aria_label.replace(' ', '_')}", tab)

                            # Close emoji picker
                            self.driver.find_element(By.TAG_NAME, "body").click()
                            time.sleep(0.5)
                            break
                        except:
                            continue

                # Message actions (right-click menu)
                print("  🔍 Mapping message context menu...")
                messages = self.driver.find_elements(By.CSS_SELECTOR, "div[role='row']")
                if messages:
                    # Find a message bubble
                    for msg in messages[-5:]:  # Check last 5 messages
                        try:
                            actions = ActionChains(self.driver)
                            actions.context_click(msg).perform()
                            time.sleep(1)

                            context_items = self.driver.find_elements(By.CSS_SELECTOR, "li[role='button']")
                            for item in context_items:
                                aria_label = item.get_attribute("aria-label")
                                if aria_label:
                                    self.add_element("chat_interface", f"message_action_{aria_label.replace(' ', '_')}", item)

                            # Close context menu
                            self.driver.find_element(By.TAG_NAME, "body").click()
                            time.sleep(0.5)
                            break
                        except:
                            continue

                # Chat menu (3 dots in header)
                print("  🔍 Mapping chat menu...")
                chat_menu_buttons = self.driver.find_elements(By.CSS_SELECTOR, "header button[aria-label='Menu']")
                if chat_menu_buttons:
                    chat_menu_buttons[0].click()
                    time.sleep(1)

                    menu_items = self.driver.find_elements(By.CSS_SELECTOR, "div[role='button']")
                    for item in menu_items:
                        if item.text:
                            self.add_element("chat_interface", f"chat_menu_{item.text.lower().replace(' ', '_')}", item)

                    # Close menu
                    self.driver.find_element(By.TAG_NAME, "body").click()
                    time.sleep(0.5)

        except Exception as e:
            print(f"  ⚠️ Error mapping chat interface: {e}")

    def map_status_section(self):
        """Map Status/Updates section"""
        self.map_section("status", "WhatsApp Status/Updates features")

        try:
            # Click Status tab
            print("  🔍 Navigating to Status section...")
            status_tabs = self.driver.find_elements(By.CSS_SELECTOR, "button[aria-label*='Status'], button[aria-label*='Updates']")
            if status_tabs:
                status_tabs[0].click()
                time.sleep(2)

                # My Status
                my_status = self.driver.find_elements(By.CSS_SELECTOR, "div[aria-label*='My status'], div[aria-label*='My Status']")
                if my_status:
                    self.add_element("status", "my_status", my_status[0])

                # Status creation buttons
                status_buttons = self.driver.find_elements(By.CSS_SELECTOR, "span[data-icon='pencil'], span[data-icon='camera']")
                for btn in status_buttons:
                    icon = btn.get_attribute("data-icon")
                    if icon:
                        try:
                            parent = btn.find_element(By.XPATH, "./ancestor::button[1]")
                            self.add_element("status", f"status_{icon}_button", parent)
                        except:
                            pass

                # Go back to chats
                back_buttons = self.driver.find_elements(By.CSS_SELECTOR, "span[data-icon='back']")
                if back_buttons:
                    try:
                        parent = back_buttons[0].find_element(By.XPATH, "./ancestor::button[1]")
                        parent.click()
                        time.sleep(1)
                    except:
                        pass

        except Exception as e:
            print(f"  ⚠️ Error mapping status section: {e}")

    def map_settings(self):
        """Map Settings interface"""
        self.map_section("settings", "Settings and configuration options")

        try:
            # Click Settings
            print("  🔍 Opening Settings...")
            settings_buttons = self.driver.find_elements(By.CSS_SELECTOR, "button[aria-label='Settings']")
            if settings_buttons:
                settings_buttons[0].click()
                time.sleep(2)

                # Settings menu items
                settings_items = self.driver.find_elements(By.CSS_SELECTOR, "div[role='button']")
                for item in settings_items:
                    if item.text:
                        self.add_element("settings", f"setting_{item.text.lower().replace(' ', '_')}", item)

                # Click Profile
                profile_items = [i for i in settings_items if 'profile' in i.text.lower()]
                if profile_items:
                    profile_items[0].click()
                    time.sleep(2)

                    # Profile edit elements
                    profile_edits = self.driver.find_elements(By.CSS_SELECTOR, "span[data-icon='pencil'], span[data-icon='camera']")
                    for edit in profile_edits:
                        icon = edit.get_attribute("data-icon")
                        if icon:
                            try:
                                parent = edit.find_element(By.XPATH, "./ancestor::button[1]")
                                self.add_element("settings", f"profile_edit_{icon}", parent)
                            except:
                                pass

                    # Go back
                    back_buttons = self.driver.find_elements(By.CSS_SELECTOR, "span[data-icon='back']")
                    if back_buttons:
                        try:
                            parent = back_buttons[0].find_element(By.XPATH, "./ancestor::button[1]")
                            parent.click()
                            time.sleep(1)
                            parent.click()  # Back twice to get to main
                            time.sleep(1)
                        except:
                            pass

        except Exception as e:
            print(f"  ⚠️ Error mapping settings: {e}")

    def map_new_chat_flow(self):
        """Map new chat creation workflow"""
        self.map_section("new_chat_workflow", "Creating new chats and groups")

        try:
            print("  🔍 Mapping new chat flow...")
            new_chat_buttons = self.driver.find_elements(By.CSS_SELECTOR, "div[aria-label='New chat']")
            if new_chat_buttons:
                self.add_element("new_chat_workflow", "new_chat_button", new_chat_buttons[0])
                new_chat_buttons[0].click()
                time.sleep(2)

                # New chat panel elements
                search_inputs = self.driver.find_elements(By.CSS_SELECTOR, "div[contenteditable='true'][data-tab]")
                for inp in search_inputs:
                    if inp.is_displayed():
                        self.add_element("new_chat_workflow", "contact_search", inp)
                        break

                # New group button
                new_group_buttons = self.driver.find_elements(By.CSS_SELECTOR, "div[role='button']")
                for btn in new_group_buttons:
                    if 'group' in btn.text.lower():
                        self.add_element("new_chat_workflow", "new_group_button", btn)
                        break

                # Close new chat
                back_buttons = self.driver.find_elements(By.CSS_SELECTOR, "span[data-icon='back']")
                if back_buttons:
                    try:
                        parent = back_buttons[0].find_element(By.XPATH, "./ancestor::button[1]")
                        parent.click()
                        time.sleep(1)
                    except:
                        pass

                # Add workflow
                self.add_workflow("new_chat_workflow", "create_new_chat", [
                    {"step": 1, "action": "Click 'New chat' button", "element": "new_chat_button"},
                    {"step": 2, "action": "Type contact name or number in search", "element": "contact_search"},
                    {"step": 3, "action": "Click on contact from results", "element": "contact_result"},
                    {"step": 4, "action": "Chat opens, ready to send messages", "element": "message_input_box"}
                ])

        except Exception as e:
            print(f"  ⚠️ Error mapping new chat flow: {e}")

    def generate_comprehensive_report(self):
        """Generate detailed reports"""
        print(f"\n{'='*60}")
        print("📊 GENERATING COMPREHENSIVE REPORTS")
        print(f"{'='*60}\n")

        # Save JSON mapping
        json_path = "whatsapp_elements_COMPLETE.json"
        with open(json_path, 'w', encoding='utf-8') as f:
            json.dump(self.elements_mapping, f, indent=2, ensure_ascii=False)
        print(f"✅ Saved comprehensive JSON: {json_path}")

        # Generate readable markdown report
        md_path = "WHATSAPP_MAPPING_COMPLETE.md"
        with open(md_path, 'w', encoding='utf-8') as f:
            f.write("# Complete WhatsApp Web Element Mapping\n\n")
            f.write(f"**Generated:** {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}  \n")
            f.write(f"**Version:** {self.elements_mapping['version']}  \n\n")

            total_elements = sum(len(section['elements']) for section in self.elements_mapping['sections'].values())
            total_workflows = sum(len(section['workflows']) for section in self.elements_mapping['sections'].values())

            f.write(f"**Total Elements Captured:** {total_elements}  \n")
            f.write(f"**Total Workflows Documented:** {total_workflows}  \n")
            f.write(f"**Total Sections:** {len(self.elements_mapping['sections'])}  \n\n")

            f.write("---\n\n")

            for section_name, section_data in self.elements_mapping['sections'].items():
                f.write(f"## {section_name.replace('_', ' ').title()}\n\n")
                f.write(f"*{section_data['description']}*\n\n")

                # Elements table
                if section_data['elements']:
                    f.write("### Elements\n\n")
                    f.write("| Element | aria-label | data-icon | CSS Selector | XPath |\n")
                    f.write("|---------|------------|-----------|--------------|-------|\n")

                    for elem_name, elem_data in section_data['elements'].items():
                        aria = elem_data.get('aria-label', '')[:30]
                        icon = elem_data.get('data-icon', '')
                        css = elem_data.get('css_selector', '')[:40]
                        xpath = elem_data.get('xpath', '')[:50]
                        f.write(f"| `{elem_name}` | {aria} | {icon} | {css} | {xpath}... |\n")

                    f.write("\n")

                # Workflows
                if section_data['workflows']:
                    f.write("### Workflows\n\n")
                    for workflow_name, workflow_data in section_data['workflows'].items():
                        f.write(f"#### {workflow_name.replace('_', ' ').title()}\n\n")
                        for step in workflow_data['steps']:
                            f.write(f"{step['step']}. **{step['action']}**")
                            if 'element' in step:
                                f.write(f" → `{step['element']}`")
                            f.write("\n")
                        f.write("\n")

                f.write("---\n\n")

        print(f"✅ Saved markdown report: {md_path}")

        # Statistics
        print(f"\n📈 MAPPING STATISTICS:")
        print(f"   Total Sections: {len(self.elements_mapping['sections'])}")
        print(f"   Total Elements: {total_elements}")
        print(f"   Total Workflows: {total_workflows}")

        for section_name, section_data in self.elements_mapping['sections'].items():
            elem_count = len(section_data['elements'])
            workflow_count = len(section_data['workflows'])
            print(f"   - {section_name}: {elem_count} elements, {workflow_count} workflows")

    def run_complete_mapping(self):
        """Run the complete mapping process"""
        print("\n" + "="*60)
        print("🚀 COMPREHENSIVE WHATSAPP WEB MAPPING")
        print("="*60 + "\n")

        print("This will systematically map EVERY element in WhatsApp Web")
        print("Please ensure you're logged in to WhatsApp Web\n")

        input("Press ENTER to start mapping...")

        try:
            # Map all sections
            self.map_main_interface()
            time.sleep(1)

            self.map_chat_interface()
            time.sleep(1)

            self.map_status_section()
            time.sleep(1)

            self.map_new_chat_flow()
            time.sleep(1)

            self.map_settings()
            time.sleep(1)

            # Generate reports
            self.generate_comprehensive_report()

            print("\n" + "="*60)
            print("✅ MAPPING COMPLETE!")
            print("="*60 + "\n")

        except Exception as e:
            print(f"\n❌ Error during mapping: {e}")
            import traceback
            traceback.print_exc()

        return self.elements_mapping


if __name__ == "__main__":
    mapper = WhatsAppElementMapper()
    mapping = mapper.run_complete_mapping()

    print("\n📁 Generated Files:")
