"""
Complete WhatsApp Web Element Extractor
Run this script to extract ALL elements with exact selectors and workflows
"""

from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.action_chains import ActionChains
import json
import time

def extract_all_elements():
    """Extract ALL WhatsApp Web elements with exact selectors"""

    print("🔍 Starting Complete WhatsApp Web Element Extraction...")

    # Use existing Chrome session
    options = webdriver.ChromeOptions()
    options.add_argument(r"user-data-dir=C:\\Users\\ROOMMATES\\AppData\\Local\\Google\\Chrome\\User Data")
    options.add_argument("profile-directory=Default")

    driver = webdriver.Chrome(options=options)
    driver.get("https://web.whatsapp.com/")

    input("⏸️  Press Enter when WhatsApp Web is fully loaded...")

    elements = {
        "mappingLog": [],
        "selectors": {}
    }

    def log_element(name, element, category):
        """Log element details"""
        try:
            xpath = driver.execute_script(
                "function getXPath(element) {"
                "  var xpath = '';"
                "  for (; element && element.nodeType == 1; element = element.parentNode) {"
                "    var id = element.id ? \"[@id='\" + element.id + \"']\" : '';"
                "    var className = element.className ? \"[@class='\" + element.className + \"']\" : '';"
                "    var role = element.getAttribute('role') ? \"[@role='\" + element.getAttribute('role') + \"']\" : '';"
                "    var ariaLabel = element.getAttribute('aria-label') ? \"[@aria-label='\" + element.getAttribute('aria-label') + \"']\" : '';"
                "    var dataIcon = element.getAttribute('data-icon') ? \"[@data-icon='\" + element.getAttribute('data-icon') + \"']\" : '';"
                "    var dataTab = element.getAttribute('data-tab') ? \"[@data-tab='\" + element.getAttribute('data-tab') + \"']\" : '';"
                "    xpath = '/' + element.tagName.toLowerCase() + (id || className || role || ariaLabel || dataIcon || dataTab) + xpath;"
                "  }"
                "  return xpath;"
                "}"
                "return getXPath(arguments[0]);",
                element
            )

            info = {
                "name": name,
                "category": category,
                "xpath": xpath,
                "tag": element.tag_name,
                "text": element.text[:50] if element.text else "",
                "attributes": {
                    "id": element.get_attribute("id"),
                    "class": element.get_attribute("class"),
                    "role": element.get_attribute("role"),
                    "aria-label": element.get_attribute("aria-label"),
                    "data-icon": element.get_attribute("data-icon"),
                    "data-tab": element.get_attribute("data-tab"),
                    "title": element.get_attribute("title")
                }
            }

            # Clean None values
            info["attributes"] = {k: v for k, v in info["attributes"].items() if v}

            elements["mappingLog"].append(info)
            print(f"✅ {name}: {info['attributes']}")

            return info
        except Exception as e:
            print(f"❌ Error logging {name}: {e}")
            return None

    # PHASE 1: Main Interface
    print("\n📍 PHASE 1: Main Interface Elements")

    try:
        # Tabs
        tabs = driver.find_elements(By.XPATH, "//button[contains(@aria-label,'Chat') or contains(@aria-label,'Status') or contains(@aria-label,'Channel') or contains(@aria-label,'Communities') or contains(@aria-label,'Tools') or contains(@aria-label,'Settings')]")
        for i, tab in enumerate(tabs):
            log_element(f"Tab_{i}_{tab.get_attribute('aria-label')}", tab, "navigation_tabs")

        # Header buttons
        profile_btn = driver.find_element(By.XPATH, "//div[@aria-label='Profile' or contains(@title,'Profile')]")
        log_element("Profile_Button", profile_btn, "header")

        new_chat_btn = driver.find_element(By.XPATH, "//div[@aria-label='New chat' or @title='New chat']")
        log_element("New_Chat_Button", new_chat_btn, "header")

        menu_btn = driver.find_element(By.XPATH, "//div[@aria-label='Menu' or @title='Menu']")
        log_element("Menu_Button", menu_btn, "header")

        # Search
        search = driver.find_element(By.XPATH, "//div[@contenteditable='true'][@data-tab='3']")
        log_element("Search_Input", search, "search")

        # Filters
        filters = driver.find_elements(By.XPATH, "//button[contains(@class,'filter') or @role='tab']")
        for i, f in enumerate(filters):
            log_element(f"Filter_{i}_{f.text}", f, "filters")

    except Exception as e:
        print(f"❌ Phase 1 error: {e}")

    # PHASE 2: Open a chat
    print("\n📍 PHASE 2: Opening Chat...")

    try:
        wait = WebDriverWait(driver, 20)
        # Use a more specific XPath, waiting for the chat list to be ready.
        chat_list_selector = "//div[@id='pane-side']//div[@role='listitem']"
        wait.until(EC.presence_of_element_located((By.XPATH, chat_list_selector)))

        chats = driver.find_elements(By.XPATH, chat_list_selector)
        if chats:
            chats[0].click()
            time.sleep(2)
            print("✅ Chat opened")
        else:
            print("❌ No chats found, even after waiting.")
    except Exception as e:
        print(f"❌ Could not open chat: {e}")

    # PHASE 3: Chat Header Elements
    print("\n📍 PHASE 3: Chat Header Elements")

    try:
        contact_header = driver.find_element(By.XPATH, "//header//div[@role='button']")
        log_element("Contact_Info_Header", contact_header, "chat_header")

        voice_call = driver.find_element(By.XPATH, "//div[@aria-label='Voice call']")
        log_element("Voice_Call_Button", voice_call, "chat_header")

        video_call = driver.find_element(By.XPATH, "//div[@aria-label='Video call']")
        log_element("Video_Call_Button", video_call, "chat_header")

        search_chat = driver.find_element(By.XPATH, "//div[@aria-label='Search' or @title='Search']")
        log_element("Search_In_Chat_Button", search_chat, "chat_header")

        chat_menu = driver.find_element(By.XPATH, "//header//div[@aria-label='Menu']")
        log_element("Chat_Menu_Button", chat_menu, "chat_header")

    except Exception as e:
        print(f"❌ Phase 3 error: {e}")

    # PHASE 4: Message Input Area
    print("\n📍 PHASE 4: Message Input Area")

    try:
        msg_input = driver.find_element(By.XPATH, "//div[@contenteditable='true'][@data-tab='10']")
        log_element("Message_Input_Box", msg_input, "input_area")

        emoji_btn = driver.find_element(By.XPATH, "//div[@aria-label='Emoji']")
        log_element("Emoji_Button", emoji_btn, "input_area")

        attach_btn = driver.find_element(By.XPATH, "//div[@title='Attach' or contains(@aria-label,'Attach')]")
        log_element("Attach_Button", attach_btn, "input_area")

        try:
            voice_btn = driver.find_element(By.XPATH, "//span[@data-icon='ptt']")
            log_element("Voice_Message_Button", voice_btn, "input_area")
        except:
            print("ℹ️  Voice button not visible (appears when no text)")

    except Exception as e:
        print(f"❌ Phase 4 error: {e}")

    # PHASE 5: Open Emoji Picker
    print("\n📍 PHASE 5: Emoji Picker Elements")

    try:
        emoji_btn.click()
        time.sleep(1)

        emoji_tab = driver.find_element(By.XPATH, "//button[contains(@aria-label,'Emoji') or @data-tab='1']")
