        log_element("GIF_Tab", gif_tab, "emoji_picker")

        sticker_tab = driver.find_element(By.XPATH, "//span[@data-icon='sticker']")
        log_element("Sticker_Tab", sticker_tab, "emoji_picker")

        # Close emoji picker
        driver.find_element(By.TAG_NAME, 'body').send_keys(Keys.ESCAPE)
