    except Exception as e:
        print(f"❌ Phase 6 error: {e}")

    # PHASE 7: Message Actions
    print("\n📍 PHASE 7: Message Action Elements")

    try:
        messages = driver.find_elements(By.XPATH, "//div[@role='row']")
