        """Load selectors from JSON file"""
        selector_file = os.path.join(os.path.dirname(__file__), "whatsapp_selectors.json")
        try:
            with open(selector_file, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            print(f"Warning: Selectors file not found at {selector_file}")
            return {}

    def _wait_and_find(self, xpath: str, timeout: int = 10):
        """Helper to wait for and find element"""
        return WebDriverWait(self.driver, timeout).until(
            EC.presence_of_element_located((By.XPATH, xpath))
        )

    def _wait_and_click(self, xpath: str, timeout: int = 10):
        """Helper to wait for and click element"""
        element = WebDriverWait(self.driver, timeout).until(
            EC.element_to_be_clickable((By.XPATH, xpath))
        )
        element.click()
        return element

    def _navigate_to_chat(self, contact_name: str) -> bool:
        """Navigate to a specific chat"""
        try:
            search_box_xpath = self.selectors['navigation']['search']['input']['xpath']
            search_box = self._wait_and_find(search_box_xpath)
            search_box.clear()
            search_box.send_keys(contact_name)

            # Dynamic xpath for the contact name
            contact_xpath = f"//span[@title='{contact_name}']"
            self._wait_and_click(contact_xpath)
            return True
        except (KeyError, NoSuchElementException, TimeoutException) as e:
            print(f"Error navigating to chat '{contact_name}': {e}")
            return False

    # ========================================================================
    # CATEGORY 1: CORE MESSAGING
    # ========================================================================

    def send_message(self, text: str) -> bool:
        """Send a text message in the current chat"""
        try:
            message_box_xpath = self.selectors['message_input']['text_box']['xpath']
            message_box = self._wait_and_find(message_box_xpath)
            message_box.send_keys(text)
            message_box.send_keys(Keys.RETURN)
            # We can't easily wait for the message to be "sent", but we can wait for the input to be clear
            self.wait.until(
                lambda driver: driver.find_element(By.XPATH, message_box_xpath).text == ""
            )
            return True
        except (KeyError, NoSuchElementException, TimeoutException) as e:
            print(f"Error sending message: {e}")
            return False

    def send_message_to(self, contact_name: str, text: str) -> bool:
        """Navigate to chat and send message"""
        if self._navigate_to_chat(contact_name):
            return self.send_message(text)
        return False

