    def send_image(self, image_path: str, caption: Optional[str] = None) -> bool:
        """Send image with optional caption"""
        try:
            # Click attach button
            self._wait_and_click(self.selectors['message_input']['attach_button']['xpath'])
            time.sleep(0.5)

            # Upload photo
            photo_input = self._wait_and_find(self.selectors['attachment_menu']['photos_videos']['input_xpath'])
            photo_input.send_keys(os.path.abspath(image_path))
            time.sleep(1)

            # Add caption if provided
            if caption:
                caption_box = self._wait_and_find(self.selectors['message_input']['text_box']['xpath'])
                caption_box.send_keys(caption)

            # Click send
            self._wait_and_click(self.selectors['message_input']['send_button']['xpath'])
            time.sleep(1)
            return True
        except KeyError as e:
            print(f"Error: Selector not found in whatsapp_selectors.json for key {e}")
            return False
        except Exception as e:
            print(f"Error sending image: {e}")
            return False

    def send_video(self, video_path: str, caption: Optional[str] = None) -> bool:
        """Send video with optional caption"""
        return self.send_image(video_path, caption)  # Same process

