    def create_poll(self, question: str, options: List[str], allow_multiple: bool = False) -> bool:
        """Create and send a poll"""
        try:
            self._wait_and_click(self.selectors['message_input']['attach_button']['xpath'])
            time.sleep(0.5)
            self._wait_and_click(self.selectors['attachment_menu']['poll']['xpath'])
            time.sleep(0.5)

            # Enter question - assuming a generic placeholder
            question_input = self._wait_and_find("//input[@placeholder='Type a question']")
            question_input.send_keys(question)

            # Enter options (up to 12)
            for i, option in enumerate(options[:12]):
                # This selector is also dynamic and complex
                option_input = self._wait_and_find(f"//input[@placeholder='Type an option' or @placeholder='Option {i+1}']")
                option_input.send_keys(option)

            # Toggle multiple answers if needed
            if allow_multiple:
                # This selector might need to be added to the json
                self._wait_and_click("//input[@type='checkbox'][@id='allow-multiple']")

            # Send poll
            self._wait_and_click(self.selectors['message_input']['send_button']['xpath'])
            time.sleep(1)
            return True
        except KeyError as e:
            print(f"Error: Selector not found in whatsapp_selectors.json for key {e}")
            return False
        except Exception as e:
            print(f"Error creating poll: {e}")
            return False

