    def create_group(self, group_name: str, participant_numbers: List[str]) -> bool:
        """Create a new group"""
        try:
            # Open menu
            self._wait_and_click("//div[@aria-label='Menu']")
            time.sleep(0.5)
            self._wait_and_click("//div[text()='New group']")
            time.sleep(1)

            # Add participants
            for phone in participant_numbers:
                search = self._wait_and_find("//input[@placeholder='Search contacts']")
                search.send_keys(phone)
                time.sleep(0.5)

                try:
                    self._wait_and_click("//div[@role='listitem']//div[@role='checkbox']", timeout=3)
                    time.sleep(0.3)
                except TimeoutException:
                    print(f"Warning: Could not find contact for {phone}")

                search.clear()

            # Click Next
            self._wait_and_click("//span[@data-icon='forward']")
            time.sleep(1)

            # Enter group name
            name_input = self._wait_and_find("//div[@contenteditable='true']")
            name_input.send_keys(group_name)
            time.sleep(0.5)

            # Create group
            self._wait_and_click("//span[@data-icon='checkmark']")
            time.sleep(2)
            return True
        except Exception as e:
            print(f"Error creating group: {e}")
            return False

