            time.sleep(1)

            # Click add participants
            self._wait_and_click("//div[@aria-label='Add participants']")
            time.sleep(1)

            for phone in phone_numbers:
                search = self._wait_and_find("//input[@placeholder='Search…']")
                search.send_keys(phone)
                time.sleep(0.5)

                try:
                    self._wait_and_click("//div[@role='listitem']//div[@role='checkbox']", timeout=3)
